layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(50, 57, 69); border-radius: 8px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: italic; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 16px; padding-bottom: 16px; padding-left: 16px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: rgb(116, 192, 252); font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 700; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(116, 192, 252); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(116, 192, 252); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(116, 192, 252); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: rgb(116, 192, 252); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 700; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(116, 192, 252); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
